"""Generated by OpenAI Codex on 2026-11-03. Never writes the real campus file."""

import os
from xml.etree import ElementTree as ET

os.environ.setdefault("DATABASE_URL", "sqlite://")

import pytest
from fastapi.testclient import TestClient
from api.main import app
from api.routers.map_editor import editor

SOURCE = b"""<osm version="0.6"><node id="1" lat="43" lon="-84"/><node id="2" lat="43.1" lon="-84"/><node id="3" lat="43" lon="-84.1"/><way id="4"><nd ref="1"/><nd ref="2"/><nd ref="3"/><nd ref="1"/><tag k="building" v="yes"/></way><relation id="5"><member type="way" ref="4" role="outer"/><member type="way" ref="999" role="outer"/><tag k="type" v="multipolygon"/></relation></osm>"""


@pytest.fixture
def client(tmp_path, monkeypatch):
    path = tmp_path / "campus.osm"
    path.write_bytes(SOURCE)
    monkeypatch.setattr(editor, "OSM_PATH", path)
    monkeypatch.setenv("CATS_MAP_EDITOR", "1")
    monkeypatch.setenv("AUTH_REQUIRED", "0")
    with TestClient(
        app,
        base_url="http://localhost:8000",
        client=("127.0.0.1", 12000),
        headers={"origin": "http://localhost:8081"},
    ) as client:
        yield client


def write(client, xml, revision=None):
    return client.post(
        "/api/map-editor",
        json={"xml": xml, "revision": revision or editor.revision(SOURCE)},
        headers={"x-map-editor-token": editor.TOKEN},
    )


def test_save_backup_and_conflict(client):
    loaded = client.get("/api/map-editor")
    assert loaded.status_code == 200
    xml = SOURCE.decode().replace('k="building" v="yes"', 'k="name" v="New building"')
    assert write(client, xml).status_code == 200
    assert editor.OSM_PATH.read_text() == xml
    assert (
        list((editor.OSM_PATH.parent / ".osm-backups").glob("*.osm"))[0].read_bytes()
        == SOURCE
    )
    assert write(client, SOURCE.decode()).status_code == 409
    assert editor.OSM_PATH.read_text() == xml


@pytest.mark.parametrize(
    "xml",
    [
        '<osm version="0.6"/>',
        SOURCE.decode().replace('ref="2"', 'ref="777"'),
        SOURCE.decode().replace('lat="43"', 'lat="nan"'),
        SOURCE.decode().replace('lat="43"', 'lat="91"'),
        SOURCE.decode().replace(
            '<tag k="building" v="yes"/>', '<tag k="name" v="a"/><tag k="name" v="b"/>'
        ),
        '<!DOCTYPE osm [<!ENTITY a "unsafe">]>' + SOURCE.decode(),
        "<osm>",
    ],
)
def test_reject_invalid_without_changing_file(client, xml):
    assert write(client, xml).status_code == 422
    assert editor.OSM_PATH.read_bytes() == SOURCE
    assert not (editor.OSM_PATH.parent / ".osm-backups").exists()


def test_add_entrance_and_polygon_preserves_relation(client):
    root = ET.fromstring(SOURCE)
    ET.SubElement(root, "node", id="-1", lat="43.05", lon="-84").append(
        ET.Element("tag", k="entrance", v="yes")
    )
    way = root.find("way")
    way.insert(1, ET.Element("nd", ref="-1"))
    new = ET.SubElement(root, "way", id="-1")
    for ref in ["1", "-1", "3", "1"]:
        ET.SubElement(new, "nd", ref=ref)
    ET.SubElement(new, "tag", k="amenity", v="parking")
    assert write(client, ET.tostring(root, encoding="unicode")).status_code == 200
    saved = ET.fromstring(editor.OSM_PATH.read_bytes())
    assert len(saved.find("relation").findall("member")) == 2
    assert saved.find("node[@id='-1']/tag").get("v") == "yes"


def test_authorization_boundaries(client, monkeypatch):
    assert client.post("/api/map-editor", json={}).status_code == 403
    assert (
        client.get(
            "/api/map-editor", headers={"origin": "https://evil.example"}
        ).status_code
        == 403
    )
    assert (
        client.get("/api/map-editor", headers={"host": "evil.example"}).status_code
        == 403
    )
    monkeypatch.setenv("AUTH_REQUIRED", "1")
    assert client.get("/api/map-editor").status_code == 404
    monkeypatch.setenv("AUTH_REQUIRED", "0")
    monkeypatch.delenv("CATS_MAP_EDITOR")
    assert client.get("/api/map-editor").status_code == 404


def test_remote_peer_rejected(client):
    with TestClient(
        app,
        base_url="http://localhost:8000",
        client=("10.0.0.1", 1000),
        headers={"origin": "http://localhost:8081"},
    ) as remote:
        assert remote.get("/api/map-editor").status_code == 403
